CREATE TYPE match_lifecycle AS ENUM ('waiting','active','completed','expired');
CREATE TYPE player_color AS ENUM ('white','black');
CREATE TYPE match_result AS ENUM ('white','black','draw');
CREATE TYPE ending_cause AS ENUM ('checkmate','stalemate','insufficient_material','resignation','forfeit','move_limit');
CREATE TABLE matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lifecycle match_lifecycle NOT NULL DEFAULT 'waiting', fen text NOT NULL, revision bigint NOT NULL DEFAULT 0, turn player_color NOT NULL DEFAULT 'white', turn_deadline timestamptz, waiting_expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), activated_at timestamptz, completed_at timestamptz, result match_result, ending_cause ending_cause, move_count integer NOT NULL DEFAULT 0, match_hash text NOT NULL UNIQUE, match_ciphertext text, public_slug text UNIQUE);
CREATE TABLE player_seats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, color player_color NOT NULL, ready boolean NOT NULL DEFAULT false, token_hash text NOT NULL UNIQUE, token_ciphertext text, UNIQUE(match_id,color));
CREATE TABLE agent_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seat_id uuid NOT NULL REFERENCES player_seats(id) ON DELETE CASCADE, fingerprint text NOT NULL, client_name text NOT NULL, client_version text NOT NULL, model text, user_agent text NOT NULL, first_seen_at timestamptz NOT NULL DEFAULT now(), UNIQUE(seat_id,fingerprint));
CREATE TABLE moves (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, profile_id uuid NOT NULL REFERENCES agent_profiles(id), ply integer NOT NULL, before_revision bigint NOT NULL, after_revision bigint NOT NULL, "from" text NOT NULL, "to" text NOT NULL, promotion text, san text NOT NULL, fen text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), response jsonb NOT NULL, UNIQUE(match_id,ply));
CREATE UNIQUE INDEX move_retry_idx ON moves(match_id,profile_id,before_revision,"from","to",COALESCE(promotion,''));
CREATE TABLE match_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, revision bigint NOT NULL, type text NOT NULL, color player_color, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, profile_id uuid NOT NULL, revision bigint NOT NULL, kind text NOT NULL, fingerprint text NOT NULL, response jsonb NOT NULL, UNIQUE(match_id,profile_id,revision,kind,fingerprint));
CREATE INDEX matches_completed_idx ON matches(completed_at DESC) WHERE lifecycle='completed';
